/**
 * Tests for `observability.ts` — counters used to instrument the Slack modal
 * funnel. Strategy is in-memory counters + structured `console.log` lines
 * (lightest path; consumed by log aggregation). Tests assert:
 *
 *   - Each counter helper increments the right bucket exactly once per call.
 *   - Snapshots return a frozen-shape object so assertion code can structurally
 *     compare without coupling to Map internals.
 *   - The reset helper clears every bucket so test isolation works.
 *   - Each helper emits a single structured `console.log` line tagged
 *     `[modal-metrics]` so log aggregators can filter on it.
 *   - Multi-detect bucket-clamping: any `N >= 4` rolls into the `4+` bucket so
 *     the cardinality stays bounded as fan-out grows.
 *
 * Runs as a pure unit test — no DB, no Slack mock, no env mutation.
 */

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import {
  recordMultiDetectFanOut,
  recordProposalLifecycleTransition,
  recordValidatorRejection,
  resetMetrics,
  snapshotMetrics,
} from "./observability";

describe("recordProposalLifecycleTransition", () => {
  beforeEach(() => {
    resetMetrics();
  });

  afterEach(() => {
    resetMetrics();
    vi.restoreAllMocks();
  });

  it("increments the proposal_created bucket", () => {
    recordProposalLifecycleTransition("proposal_created");
    const snap = snapshotMetrics();
    expect(snap.proposalLifecycle.proposal_created).toBe(1);
    expect(snap.proposalLifecycle.proposal_submitted).toBe(0);
    expect(snap.proposalLifecycle.proposal_cancelled).toBe(0);
    expect(snap.proposalLifecycle.proposal_expired).toBe(0);
    expect(snap.proposalLifecycle.proposal_failed).toBe(0);
  });

  it("increments multiple lifecycle buckets independently", () => {
    recordProposalLifecycleTransition("proposal_created");
    recordProposalLifecycleTransition("proposal_created");
    recordProposalLifecycleTransition("proposal_submitted");
    recordProposalLifecycleTransition("proposal_cancelled");
    recordProposalLifecycleTransition("proposal_expired");
    recordProposalLifecycleTransition("proposal_failed");
    recordProposalLifecycleTransition("proposal_failed");

    const snap = snapshotMetrics();
    expect(snap.proposalLifecycle.proposal_created).toBe(2);
    expect(snap.proposalLifecycle.proposal_submitted).toBe(1);
    expect(snap.proposalLifecycle.proposal_cancelled).toBe(1);
    expect(snap.proposalLifecycle.proposal_expired).toBe(1);
    expect(snap.proposalLifecycle.proposal_failed).toBe(2);
  });

  it("emits a structured log line tagged [modal-metrics]", () => {
    const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
    recordProposalLifecycleTransition("proposal_submitted", {
      proposalId: "prop_xxx",
      toolName: "create_project",
    });
    expect(logSpy).toHaveBeenCalledTimes(1);
    const [tag, payload] = logSpy.mock.calls[0];
    expect(tag).toBe("[modal-metrics]");
    expect(payload).toMatchObject({
      kind: "proposal_lifecycle",
      event: "proposal_submitted",
      proposalId: "prop_xxx",
      toolName: "create_project",
    });
  });
});

describe("recordValidatorRejection", () => {
  beforeEach(() => {
    resetMetrics();
  });

  afterEach(() => {
    resetMetrics();
    vi.restoreAllMocks();
  });

  it("increments per-rule rejection counts", () => {
    recordValidatorRejection("validateRoleTagOnResources");
    recordValidatorRejection("validateRoleTagOnResources");
    recordValidatorRejection("validateStatusCategoryCompatibility");

    const snap = snapshotMetrics();
    expect(snap.validatorRejections.validateRoleTagOnResources).toBe(2);
    expect(snap.validatorRejections.validateStatusCategoryCompatibility).toBe(1);
  });

  it("returns 0 for rules never seen", () => {
    const snap = snapshotMetrics();
    expect(snap.validatorRejections.unknownRule).toBeUndefined();
  });

  it("emits a structured log line carrying rule + modalKind", () => {
    const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
    recordValidatorRejection("validateRoleTagOnResources", "task");
    expect(logSpy).toHaveBeenCalledTimes(1);
    const [tag, payload] = logSpy.mock.calls[0];
    expect(tag).toBe("[modal-metrics]");
    expect(payload).toMatchObject({
      kind: "validator_rejection",
      rule: "validateRoleTagOnResources",
      modalKind: "task",
    });
  });

  it("modalKind is optional", () => {
    const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
    recordValidatorRejection("validateNotesMaxLength");
    expect(logSpy).toHaveBeenCalledTimes(1);
    const payload = logSpy.mock.calls[0][1] as Record<string, unknown>;
    expect(payload.modalKind).toBeUndefined();
    expect(payload.rule).toBe("validateNotesMaxLength");
  });
});

describe("recordMultiDetectFanOut", () => {
  beforeEach(() => {
    resetMetrics();
  });

  afterEach(() => {
    resetMetrics();
    vi.restoreAllMocks();
  });

  it("increments the N=2 bucket for two-item fan-outs", () => {
    recordMultiDetectFanOut(2, "ig_001");
    const snap = snapshotMetrics();
    expect(snap.multiDetectFanOut["2"]).toBe(1);
    expect(snap.multiDetectFanOut["3"]).toBe(0);
    expect(snap.multiDetectFanOut["4+"]).toBe(0);
  });

  it("increments the N=3 bucket for three-item fan-outs", () => {
    recordMultiDetectFanOut(3, "ig_002");
    const snap = snapshotMetrics();
    expect(snap.multiDetectFanOut["3"]).toBe(1);
  });

  it("clamps N>=4 into the 4+ bucket", () => {
    recordMultiDetectFanOut(4, "ig_003");
    recordMultiDetectFanOut(5, "ig_004");
    recordMultiDetectFanOut(12, "ig_005");
    const snap = snapshotMetrics();
    expect(snap.multiDetectFanOut["4+"]).toBe(3);
  });

  it("ignores N<2 (single-detect is not a fan-out)", () => {
    recordMultiDetectFanOut(0, "ig_006");
    recordMultiDetectFanOut(1, "ig_007");
    const snap = snapshotMetrics();
    expect(snap.multiDetectFanOut["2"]).toBe(0);
    expect(snap.multiDetectFanOut["3"]).toBe(0);
    expect(snap.multiDetectFanOut["4+"]).toBe(0);
  });

  it("emits a structured log line carrying intentGroupId + bucketed N", () => {
    const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
    recordMultiDetectFanOut(7, "ig_log_001");
    expect(logSpy).toHaveBeenCalledTimes(1);
    const [tag, payload] = logSpy.mock.calls[0];
    expect(tag).toBe("[modal-metrics]");
    expect(payload).toMatchObject({
      kind: "multi_detect_fan_out",
      n: 7,
      bucket: "4+",
      intentGroupId: "ig_log_001",
    });
  });

  it("does not log for N<2", () => {
    const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
    recordMultiDetectFanOut(1, "ig_skip");
    expect(logSpy).not.toHaveBeenCalled();
  });
});

describe("snapshotMetrics + resetMetrics", () => {
  it("snapshot is independent of subsequent mutations (frozen copy)", () => {
    resetMetrics();
    recordProposalLifecycleTransition("proposal_created");
    const snap1 = snapshotMetrics();
    expect(snap1.proposalLifecycle.proposal_created).toBe(1);

    recordProposalLifecycleTransition("proposal_created");
    expect(snap1.proposalLifecycle.proposal_created).toBe(1);

    const snap2 = snapshotMetrics();
    expect(snap2.proposalLifecycle.proposal_created).toBe(2);
  });

  it("resetMetrics zeros every bucket across kinds", () => {
    recordProposalLifecycleTransition("proposal_created");
    recordValidatorRejection("ruleA");
    recordMultiDetectFanOut(3, "ig_reset");

    resetMetrics();

    const snap = snapshotMetrics();
    expect(snap.proposalLifecycle.proposal_created).toBe(0);
    expect(snap.proposalLifecycle.proposal_submitted).toBe(0);
    expect(snap.proposalLifecycle.proposal_cancelled).toBe(0);
    expect(snap.proposalLifecycle.proposal_expired).toBe(0);
    expect(snap.proposalLifecycle.proposal_failed).toBe(0);
    expect(snap.validatorRejections).toEqual({});
    expect(snap.multiDetectFanOut["2"]).toBe(0);
    expect(snap.multiDetectFanOut["3"]).toBe(0);
    expect(snap.multiDetectFanOut["4+"]).toBe(0);
  });
});

/**
 * Slack Modal observability counters — Wave 14 (pre-plan v7 §"Wave 14",
 * "Funnel observability").
 *
 * Strategy: lightweight in-memory counters paired with structured
 * `console.log` lines tagged `[modal-metrics]`. Picked over a dedicated
 * `slack_modal_metrics` DB table for two reasons:
 *
 *   1. No new schema or migration required — Phase 2 stays additive.
 *   2. Vercel's runtime log aggregation already ingests `console.*` output, so
 *      a structured tag is enough for ad-hoc queries / dashboards. If we ever
 *      need durable per-15-min rollups we can layer a flush job on top of
 *      `snapshotMetrics()` without changing the call sites.
 *
 * Three counter families per pre-plan v7 §"Wave 14":
 *
 *   - `proposal_lifecycle`     — counts of `bot_modal_proposals.status` flips
 *                                 (created / submitted / cancelled / expired /
 *                                 failed). Drives funnel-conversion metrics.
 *   - `validator_rejection`    — per-validator-rule rejection counts. Tells us
 *                                 which rule is firing most often (e.g. role-
 *                                 tagged-resources catching most modal flubs).
 *   - `multi_detect_fan_out`   — bucketed N from natural-language LLM intent
 *                                 detection (N=2 / N=3 / N=4+). Tells us how
 *                                 often users stack multi-create.
 *
 * Counters are process-local. Multiple Vercel function instances each track
 * their own; aggregation happens at the log-ingest layer. `resetMetrics()`
 * exists for test isolation.
 */

// ── Lifecycle event keys (mirrors bot_modal_proposals.status enum) ──

export type ProposalLifecycleEvent =
  | "proposal_created"
  | "proposal_submitted"
  | "proposal_cancelled"
  | "proposal_expired"
  | "proposal_failed";

const ALL_LIFECYCLE_EVENTS: ProposalLifecycleEvent[] = [
  "proposal_created",
  "proposal_submitted",
  "proposal_cancelled",
  "proposal_expired",
  "proposal_failed",
];

type LifecycleCounts = Record<ProposalLifecycleEvent, number>;
type FanOutBucket = "2" | "3" | "4+";
type FanOutCounts = Record<FanOutBucket, number>;

// ── Module-local counter state ────────────────────────────

const lifecycleCounts: LifecycleCounts = {
  proposal_created: 0,
  proposal_submitted: 0,
  proposal_cancelled: 0,
  proposal_expired: 0,
  proposal_failed: 0,
};

const validatorRejectionCounts: Record<string, number> = {};

const multiDetectFanOutCounts: FanOutCounts = {
  "2": 0,
  "3": 0,
  "4+": 0,
};

const LOG_TAG = "[modal-metrics]";

// ── Counter helpers ──────────────────────────────────────

/**
 * Record a transition in the proposal lifecycle (i.e. a `bot_modal_proposals`
 * row flipping into a new status). Increments the in-memory counter and emits
 * a structured `[modal-metrics]` log line with optional metadata so log
 * aggregation can correlate against `bot_modal_proposals` rows by id.
 *
 * Wired in:
 *   - `proposal_created`   — `insertProposal()` (Wave 3 / Builder 3 + Wave 7)
 *   - `proposal_submitted` — view_submission handler (Wave 10 / Builder 10)
 *   - `proposal_cancelled` — view_closed handler (Wave 11 / Builder 11)
 *   - `proposal_expired`   — Inngest expiry sweeper (Wave 12 / Builder 12)
 *   - `proposal_failed`    — view_submission catch-block (Wave 10)
 */
export function recordProposalLifecycleTransition(
  event: ProposalLifecycleEvent,
  metadata?: Record<string, unknown>,
): void {
  lifecycleCounts[event] += 1;
  console.log(LOG_TAG, {
    kind: "proposal_lifecycle",
    event,
    ...(metadata ?? {}),
  });
}

/**
 * Record a Wave 0b validator rejection. `rule` is the validator function name
 * (e.g. `validateRoleTagOnResources`). `modalKind` is the surface that fired
 * the rejection (`"task" | "project" | "team"`) — optional because some
 * validators run outside a modal context (CLI, MCP).
 */
export function recordValidatorRejection(
  rule: string,
  modalKind?: string,
): void {
  validatorRejectionCounts[rule] = (validatorRejectionCounts[rule] ?? 0) + 1;
  console.log(LOG_TAG, {
    kind: "validator_rejection",
    rule,
    ...(modalKind === undefined ? {} : { modalKind }),
  });
}

/**
 * Record a multi-detect fan-out — how many proposals the LLM intent extractor
 * staged from a single user message. Bucketed into `2 / 3 / 4+` to keep
 * cardinality bounded as fan-out grows. `N < 2` is silently ignored (single
 * detect is not a fan-out and isn't worth a log line).
 */
export function recordMultiDetectFanOut(
  N: number,
  intentGroupId: string,
): void {
  if (N < 2) return;
  const bucket: FanOutBucket = N === 2 ? "2" : N === 3 ? "3" : "4+";
  multiDetectFanOutCounts[bucket] += 1;
  console.log(LOG_TAG, {
    kind: "multi_detect_fan_out",
    n: N,
    bucket,
    intentGroupId,
  });
}

// ── Snapshot + reset (test isolation + future flush-job hook) ────

export interface MetricsSnapshot {
  proposalLifecycle: LifecycleCounts;
  validatorRejections: Record<string, number>;
  multiDetectFanOut: FanOutCounts;
}

/**
 * Return a structural copy of the current counter state. Mutating the
 * returned object does NOT affect the live counters; subsequent record-calls
 * advance the live counters independently. Useful for tests + a future
 * cron-driven flush job that periodically POSTs counter rollups somewhere
 * durable (out of scope for Phase 2).
 */
export function snapshotMetrics(): MetricsSnapshot {
  return {
    proposalLifecycle: { ...lifecycleCounts },
    validatorRejections: { ...validatorRejectionCounts },
    multiDetectFanOut: { ...multiDetectFanOutCounts },
  };
}

/**
 * Zero every counter. Test-only helper so each spec starts from a clean
 * baseline; production code does not call this.
 */
export function resetMetrics(): void {
  for (const ev of ALL_LIFECYCLE_EVENTS) {
    lifecycleCounts[ev] = 0;
  }
  for (const key of Object.keys(validatorRejectionCounts)) {
    delete validatorRejectionCounts[key];
  }
  multiDetectFanOutCounts["2"] = 0;
  multiDetectFanOutCounts["3"] = 0;
  multiDetectFanOutCounts["4+"] = 0;
}

/**
 * Tests for `intercept-miss-alert.ts` — Wave 14 / pre-plan v7 §A4.
 *
 * The observer factory returns an `AuditObserver` that operations-layer write
 * helpers call after every audit insert. The observer fires when:
 *
 *   1. `MODAL_INTERCEPT_ENABLED=true`, AND
 *   2. `event.source === "bot-direct"` (a non-modal bot LLM tool call), AND
 *   3. `event.entityType` is in the modal-routed allowlist (project /
 *       week_item / team_member), AND
 *   4. No `submitted` `bot_modal_proposals` row exists for the same Slack user
 *       in the last 5 minutes (decoded from `event.updatedBy` which carries
 *       the `slack:UID:bot|modal[-edit]` prefix per Wave 0b §"updatedBy
 *       format spec").
 *
 * When all four conditions hold the observer logs a `[intercept-miss]`
 * `console.warn` line. Otherwise it stays silent.
 *
 * AuditEvent today (Wave 0b output) does NOT carry `toolName` or
 * `conversationRef`. The observer compensates by:
 *   - using `entityType` as a proxy for "create_*" (the entity types in the
 *     INTERCEPT_ALLOWLIST are exactly the modal-routed surfaces); and
 *   - parsing `slack:UID:...` out of `updatedBy` to scope the lookup to one
 *     user. The original spec `user_slack_id + channel_id + intent_group_id`
 *     scope degrades to `user_slack_id + last 5 min` until the AuditEvent is
 *     enriched with channel / intent context (open follow-up, see
 *     `wave-14-complete-handoff.md`).
 */

import {
  afterEach,
  beforeEach,
  describe,
  expect,
  it,
  vi,
} from "vitest";

import type { AuditEvent } from "@/lib/runway/operations-utils";

import { createInterceptMissObserver } from "./intercept-miss-alert";

// ── DB mock plumbing ──────────────────────────────────────
//
// We replace `getRunwayDb` with a chain that captures `select().from().where().limit()`.
// Each test seeds `mockSelectResult` to control whether a "recent submitted
// proposal" exists.

const mockSelectResult = vi.fn<() => Promise<Array<{ id: string }>>>();
const limitSpy = vi.fn();
const whereSpy = vi.fn();
const fromSpy = vi.fn();

const selectChain = {
  from: (table: unknown) => {
    fromSpy(table);
    return {
      where: (cond: unknown) => {
        whereSpy(cond);
        return {
          limit: (n: number) => {
            limitSpy(n);
            return mockSelectResult();
          },
        };
      },
    };
  },
};

const mockDb = {
  select: vi.fn(() => selectChain),
};

vi.mock("@/lib/db/runway", () => ({
  getRunwayDb: () => mockDb,
}));

// ── Drizzle helper mocks (structural shapes only — no real SQL eval) ──

vi.mock("drizzle-orm", () => ({
  and: (...args: unknown[]) => ({ __op: "and", args }),
  eq: (col: unknown, val: unknown) => ({ __op: "eq", col, val }),
  gt: (col: unknown, val: unknown) => ({ __op: "gt", col, val }),
}));

// ── Test-utility: build an AuditEvent shape ──

function makeEvent(overrides: Partial<AuditEvent> = {}): AuditEvent {
  return {
    source: "bot-direct",
    entityId: "proj_abc",
    entityType: "project",
    updatedBy: "slack:U_TEST_001:bot",
    ...overrides,
  };
}

describe("createInterceptMissObserver", () => {
  const originalFlag = process.env.MODAL_INTERCEPT_ENABLED;

  beforeEach(() => {
    mockDb.select.mockClear();
    fromSpy.mockClear();
    whereSpy.mockClear();
    limitSpy.mockClear();
    mockSelectResult.mockReset();
    process.env.MODAL_INTERCEPT_ENABLED = "true";
  });

  afterEach(() => {
    if (originalFlag === undefined) {
      delete process.env.MODAL_INTERCEPT_ENABLED;
    } else {
      process.env.MODAL_INTERCEPT_ENABLED = originalFlag;
    }
    vi.restoreAllMocks();
  });

  it("warns when bot-direct project create has no recent submitted proposal", async () => {
    mockSelectResult.mockResolvedValueOnce([]); // no recent submitted proposal
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
    const observer = createInterceptMissObserver();

    await observer(makeEvent({ source: "bot-direct", entityType: "project" }));

    expect(warnSpy).toHaveBeenCalledTimes(1);
    const [tag, payload] = warnSpy.mock.calls[0];
    expect(tag).toBe("[intercept-miss]");
    expect(payload).toMatchObject({
      source: "bot-direct",
      entityType: "project",
      entityId: "proj_abc",
      userSlackId: "U_TEST_001",
    });
  });

  it("warns for week_item bot-direct creates", async () => {
    mockSelectResult.mockResolvedValueOnce([]);
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    const observer = createInterceptMissObserver();
    await observer(
      makeEvent({
        source: "bot-direct",
        entityType: "week_item",
        entityId: "wk_xyz",
        updatedBy: "slack:U_TEST_002:bot",
      }),
    );
    expect(warnSpy).toHaveBeenCalledTimes(1);
  });

  it("warns for team_member bot-direct creates", async () => {
    mockSelectResult.mockResolvedValueOnce([]);
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    const observer = createInterceptMissObserver();
    await observer(
      makeEvent({
        source: "bot-direct",
        entityType: "team_member",
        entityId: "tm_lmn",
        updatedBy: "slack:U_TEST_003:bot",
      }),
    );
    expect(warnSpy).toHaveBeenCalledTimes(1);
  });

  it("does NOT warn when source is slack-modal-bot (modal-routed)", async () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    const observer = createInterceptMissObserver();
    await observer(makeEvent({ source: "slack-modal-bot" }));

    expect(warnSpy).not.toHaveBeenCalled();
    // Lookup should be skipped entirely — no DB hit when source is excluded.
    expect(mockDb.select).not.toHaveBeenCalled();
  });

  it("does NOT warn when source is slack-modal-slash", async () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    const observer = createInterceptMissObserver();
    await observer(makeEvent({ source: "slack-modal-slash" }));

    expect(warnSpy).not.toHaveBeenCalled();
    expect(mockDb.select).not.toHaveBeenCalled();
  });

  it("does NOT warn when source is mcp / migration / cli / null", async () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    const observer = createInterceptMissObserver();
    await observer(makeEvent({ source: "mcp" }));
    await observer(makeEvent({ source: "migration" }));
    await observer(makeEvent({ source: "cli" }));
    await observer(makeEvent({ source: null }));

    expect(warnSpy).not.toHaveBeenCalled();
    expect(mockDb.select).not.toHaveBeenCalled();
  });

  it("does NOT warn when feature flag is off", async () => {
    process.env.MODAL_INTERCEPT_ENABLED = "false";
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    const observer = createInterceptMissObserver();
    await observer(makeEvent({ source: "bot-direct" }));

    expect(warnSpy).not.toHaveBeenCalled();
    expect(mockDb.select).not.toHaveBeenCalled();
  });

  it("does NOT warn when feature flag is unset", async () => {
    delete process.env.MODAL_INTERCEPT_ENABLED;
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    const observer = createInterceptMissObserver();
    await observer(makeEvent({ source: "bot-direct" }));

    expect(warnSpy).not.toHaveBeenCalled();
  });

  it("does NOT warn when there IS a recent submitted proposal for the user", async () => {
    mockSelectResult.mockResolvedValueOnce([{ id: "prop_recent_001" }]);
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    const observer = createInterceptMissObserver();
    await observer(makeEvent({ source: "bot-direct" }));

    expect(warnSpy).not.toHaveBeenCalled();
    expect(mockDb.select).toHaveBeenCalledTimes(1);
  });

  it("does NOT warn for non-allowlist entity types (e.g. pipeline)", async () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    const observer = createInterceptMissObserver();
    await observer(
      makeEvent({
        source: "bot-direct",
        // `pipeline` is intentionally NOT in INTERCEPT_ALLOWLIST per Wave 0b
        // — pipeline items live in a separate Sales-pipeline surface and
        // the modal intercept layer doesn't apply.
        entityType: undefined,
      }),
    );

    expect(warnSpy).not.toHaveBeenCalled();
    // No DB lookup either — short-circuits before the query.
    expect(mockDb.select).not.toHaveBeenCalled();
  });

  it("does NOT warn when updatedBy is missing the slack: prefix", async () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    const observer = createInterceptMissObserver();
    // Migration / CLI updatedBy formats don't carry a Slack user id and
    // cannot be matched against bot_modal_proposals. The observer skips
    // rather than emit a misleading alert.
    await observer(
      makeEvent({
        source: "bot-direct",
        updatedBy: "migration:lppc-2026-04-21",
      }),
    );

    expect(warnSpy).not.toHaveBeenCalled();
    expect(mockDb.select).not.toHaveBeenCalled();
  });

  it("queries the DB with a 5-minute lookback window", async () => {
    mockSelectResult.mockResolvedValueOnce([]);
    vi.spyOn(console, "warn").mockImplementation(() => {});
    const before = Date.now();

    const observer = createInterceptMissObserver();
    await observer(makeEvent({ source: "bot-direct" }));

    const after = Date.now();
    expect(mockDb.select).toHaveBeenCalledTimes(1);
    expect(limitSpy).toHaveBeenCalledWith(1);

    // Inspect the where-clause shape: should be an `and(eq(userSlackId), eq(status='submitted'), gt(createdAt, cutoff))`
    expect(whereSpy).toHaveBeenCalledTimes(1);
    const condArg = whereSpy.mock.calls[0][0] as {
      __op: string;
      args: Array<{ __op: string; col?: unknown; val?: unknown }>;
    };
    expect(condArg.__op).toBe("and");
    expect(condArg.args).toHaveLength(3);

    const eqs = condArg.args.filter((a) => a.__op === "eq");
    const gts = condArg.args.filter((a) => a.__op === "gt");
    expect(eqs).toHaveLength(2);
    expect(gts).toHaveLength(1);

    // Status equality must match "submitted" (the success terminal state).
    const statusEq = eqs.find((e) => e.val === "submitted");
    expect(statusEq).toBeDefined();

    // Slack user id parsed from updatedBy.
    const userEq = eqs.find((e) => e.val === "U_TEST_001");
    expect(userEq).toBeDefined();

    // Cutoff timestamp must fall within the 5-minute lookback window.
    const cutoff = (gts[0].val as Date).getTime();
    expect(cutoff).toBeGreaterThanOrEqual(before - 5 * 60 * 1000);
    expect(cutoff).toBeLessThanOrEqual(after - 5 * 60 * 1000 + 50);
  });

  it("supports the modal-edit suffix in updatedBy without false-positive (still skips when source is modal)", async () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

    // updatedBy from an edit-modal would be `slack:UID:modal-edit`, but the
    // source check trumps it — modal-edit writes never hit `bot-direct`.
    const observer = createInterceptMissObserver();
    await observer(
      makeEvent({
        source: "slack-modal-slash",
        updatedBy: "slack:U_EDIT:modal-edit",
      }),
    );

    expect(warnSpy).not.toHaveBeenCalled();
  });

  it("survives a DB error without throwing (logs but does not crash the write path)", async () => {
    mockSelectResult.mockRejectedValueOnce(new Error("boom"));
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
    const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});

    const observer = createInterceptMissObserver();
    // Must NOT throw — the observer is fire-and-forget on the write path.
    await expect(
      observer(makeEvent({ source: "bot-direct" })),
    ).resolves.toBeUndefined();

    // The intercept-miss warn is suppressed; an error log surfaces the
    // observability outage so we still notice.
    expect(warnSpy).not.toHaveBeenCalled();
    expect(errorSpy).toHaveBeenCalledTimes(1);
    const [errTag] = errorSpy.mock.calls[0];
    expect(errTag).toBe("[intercept-miss]");
  });
});

/**
 * Wave 14 / pre-plan v7 §A4 — intercept-miss alert via the `auditObserver`
 * listener pattern (NOT inline grep).
 *
 * Operations-layer write helpers (`addProject`, `createWeekItem`,
 * `createTeamMember`, etc.) accept an optional `auditObserver` callback that
 * fires after every audit insert with a structured `AuditEvent`. Production
 * code wires the observer returned by `createInterceptMissObserver()` so we
 * detect when a `bot-direct` create_* tool slipped past the modal gate while
 * `MODAL_INTERCEPT_ENABLED=true` — that's the regression the modal layer is
 * supposed to prevent.
 *
 * Detection rules (all must hold to fire the warn):
 *   1. `MODAL_INTERCEPT_ENABLED=true`
 *   2. `event.source === "bot-direct"` — non-modal bot LLM tool call
 *   3. `event.entityType ∈ ALLOWLISTED_ENTITY_TYPES` — modal-routed surface
 *   4. `updatedBy` carries a `slack:UID:` prefix (otherwise we can't scope
 *       the lookup to a specific user)
 *   5. No `bot_modal_proposals` row with `status='submitted'` exists for
 *       that Slack user in the last 5 minutes
 *
 * Original spec scoped the lookup by `user_slack_id + channel_id +
 * intent_group_id`. The `AuditEvent` shape today (Builder 0b output) carries
 * neither `channelId` nor `intentGroupId`, so this implementation degrades to
 * `user_slack_id + last 5 min`. That's still a useful regression alarm; the
 * follow-up to enrich AuditEvent with channel/intent context is tracked in
 * the Wave 14 handoff doc.
 *
 * The observer is fire-and-forget on the write path. Database failures are
 * caught and logged via `console.error` — they must NEVER throw out and
 * crash the write transaction.
 *
 * Wiring (Phase 2 follow-up): Builder 7 owns `bot-tools.ts` and is best
 * positioned to register `createInterceptMissObserver()` into the bot-direct
 * fallback path; this module only ships the factory. See
 * `wave-14-complete-handoff.md` open follow-ups.
 */

import { and, eq, gt } from "drizzle-orm";

import { getRunwayDb } from "@/lib/db/runway";
import { botModalProposals } from "@/lib/db/runway-schema";
import { isModalInterceptEnabled } from "@/lib/feature-flags";
import type { AuditEvent } from "@/lib/runway/operations-utils";

// ── Constants ────────────────────────────────────────────

/**
 * Entity types that the modal intercept layer is responsible for. Matches
 * `INTERCEPT_ALLOWLIST` in operations-utils (`create_project`,
 * `create_week_item`, `create_team_member`) but expressed at the entity
 * granularity that AuditEvent actually carries.
 */
const ALLOWLISTED_ENTITY_TYPES: ReadonlySet<NonNullable<AuditEvent["entityType"]>> = new Set([
  "project",
  "week_item",
  "team_member",
]);

const LOOKBACK_MS = 5 * 60 * 1000;
const LOG_TAG = "[intercept-miss]";

/**
 * Parse `slack:UID:bot|modal[-edit]` -> `UID`. Returns null for any updatedBy
 * format that doesn't carry a Slack user id (migration / cli / etc.) so the
 * observer can skip cleanly rather than fire false-positive alerts.
 */
function extractSlackUserId(updatedBy: string): string | null {
  const m = /^slack:([^:]+):/.exec(updatedBy);
  return m?.[1] ?? null;
}

// ── Observer ─────────────────────────────────────────────

export type AuditObserver = (event: AuditEvent) => Promise<void> | void;

/**
 * Build an `AuditObserver` callback suitable for passing to operations-layer
 * write helpers. Returns a closure so each registration site can keep its own
 * observer reference (and tests can pass a fresh closure with a clean DB
 * mock).
 *
 * Production registers this observer on the bot-direct create path (Phase 2
 * follow-up); modal-routed paths never need it because their `source` value
 * already excludes them from the alert.
 */
export function createInterceptMissObserver(): AuditObserver {
  return async (event: AuditEvent): Promise<void> => {
    // Rule 1: feature flag must be on. Cheaper than a DB hit, so check first.
    if (!isModalInterceptEnabled()) return;

    // Rule 2: only bot-direct writes can be intercept-misses. Modal-routed
    // sources, mcp, migration, cli, and pre-modal-era null all skip.
    if (event.source !== "bot-direct") return;

    // Rule 3: entity must be modal-routed. `pipeline_item` and any future
    // surface outside the allowlist short-circuits here.
    if (!event.entityType || !ALLOWLISTED_ENTITY_TYPES.has(event.entityType)) {
      return;
    }

    // Rule 4: updatedBy must carry a Slack user id we can scope the lookup
    // to. If the bot-direct write came from a non-Slack surface (shouldn't
    // happen in practice, but defensive), skip rather than alert wrongly.
    const userSlackId = extractSlackUserId(event.updatedBy);
    if (!userSlackId) return;

    // Rule 5: no recent `submitted` proposal for this user in the last 5 min.
    // Wrap the DB call so a Turso outage can't crash the write path that
    // triggered the observer.
    try {
      const db = getRunwayDb();
      const cutoff = new Date(Date.now() - LOOKBACK_MS);
      const recentSubmitted = await db
        .select({ id: botModalProposals.id })
        .from(botModalProposals)
        .where(
          and(
            eq(botModalProposals.userSlackId, userSlackId),
            eq(botModalProposals.status, "submitted"),
            gt(botModalProposals.createdAt, cutoff),
          ),
        )
        .limit(1);

      if (recentSubmitted.length > 0) {
        // The user submitted a modal in the last 5 min — this bot-direct
        // write is plausibly the resulting operations-layer call from the
        // modal submit-handler chain (or an unrelated but legitimate
        // follow-up). Either way, suppress the alert.
        return;
      }

      console.warn(LOG_TAG, {
        message:
          "bot-direct create write hit ops layer without preceding submitted modal proposal",
        source: event.source,
        entityType: event.entityType,
        entityId: event.entityId,
        userSlackId,
      });
    } catch (err) {
      console.error(LOG_TAG, {
        message: "intercept-miss lookup failed; alert suppressed",
        error: err instanceof Error ? err.message : String(err),
      });
    }
  };
}

